import {HandleInput as Fundamental} from "./2Managing State/3PreserrvingandResetting"
import Sub from "./subReLearn"
import Custom from "./customComponent"
import "./ReLearn.css"

import { useState } from "react"
import { useReducer } from "react"

export default function() {
  const [val, dispatch] = useReducer(reducer, "initialValue")
  return <>
  <button></button><br/>
  {val}
  </>
}

function reducer(value, action) {
  switch(action.a) {
    case 1:
      return "anjass"
    default:
      return "wutt"
  }
}


